"use client";

import { useSearchParams, useRouter } from "next/navigation";
import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import axios from "axios";
import Image from "next/image";
import { Formik, Form, Field, ErrorMessage } from "formik";
import * as Yup from "yup";

const fetchCategories = async ({ queryKey }) => {
  const [_key, { page, categoryName }] = queryKey;
  const { data } = await axios.get("http://localhost:8080/api/v1/categories", {
    params: { page, categoryName },
  });
  return data;
};

export default function Categories() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const queryClient = useQueryClient();
  const [modalData, setModalData] = useState(null);
  
  const page = searchParams.get("page") || 0;
  const categoryName = searchParams.get("categoryName") || "";

  const { data, isLoading } = useQuery({
    queryKey: ["categories", { page, categoryName }],
    queryFn: fetchCategories,
  });

  const updateCategoryMutation = useMutation({
    mutationFn: async (values) => {
      const formData = new FormData();
      formData.append("categoryName", values.categoryName);
      if (values.file) formData.append("file", values.file);
      await axios.patch(
        `http://localhost:8080/api/v1/categories/${modalData.id}/update`,
        formData
      );
    },
    onSuccess: () => queryClient.invalidateQueries(["categories"]),
  });

  const deleteCategoryMutation = useMutation({
    mutationFn: (id) => axios.patch(`http://localhost:8080/api/v1/categories/${id}/delete`),
    onSuccess: () => queryClient.invalidateQueries(["categories"]),
  });

  const createCategoryMutation = useMutation({
    mutationFn: async (values) => {
      const formData = new FormData();
      formData.append("categoryName", values.categoryName);
      formData.append("file", values.file);
      await axios.post("http://localhost:8080/api/v1/categories/create", formData);
    },
    onSuccess: () => queryClient.invalidateQueries(["categories"]),
  });

  if (isLoading) return <p>Loading...</p>;

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        defaultValue={categoryName}
        onChange={(e) => {
          router.push(`?page=${page}&categoryName=${e.target.value}`);
        }}
      />
      <button
        className="text-gray-500"
       onClick={() => setModalData({ create: true })}>Create Category</button>
      <div>
  {data?.data?.content?.map((category) => (
    <div key={category.id || category.categoryId} className="flex items-center">
      {category.imageUrl ? ( // ✅ Only render if imageUrl is not empty or null
        <Image 
          src={category.imageUrl} 
          width={100} 
          height={100} 
          alt={category.categoryName || "Category image"} 
        />
      ) : (
        <div className="w-[100px] h-[100px] bg-gray-200 flex items-center justify-center">
          <span>No Image</span> {/* Placeholder when no image */}
        </div>
      )}
      <p className="text-gray-500">{category.categoryName}</p>
      <button className="text-gray-500" onClick={() => setModalData(category)}>Edit</button>
      <button className="text-gray-500" onClick={() => deleteCategoryMutation.mutate(category.id)}>Delete</button>
    </div>
  ))}
</div>
      {modalData && (
        <div className="modal">
          <Formik
            initialValues={{ categoryName: modalData.categoryName || "", file: null }}
            validationSchema={Yup.object({
              categoryName: Yup.string().required("Required"),
              file: Yup.mixed()
                .nullable()
                .test("fileSize", "File too large", (value) => !value || value.size <= 1048576)
                .test(
                  "fileType",
                  "Unsupported Format",
                  (value) =>
                    !value ||
                    ["image/jpeg", "image/png", "image/jpg", "image/gif"].includes(value.type)
                ),
            })}
            onSubmit={(values) => {
              if (modalData.create) {
                createCategoryMutation.mutate(values);
              } else {
                updateCategoryMutation.mutate(values);
              }
              setModalData(null);
            }}
          >
            {({ setFieldValue }) => (
              <Form>
                <Field name="categoryName" placeholder="Category Name" />
                <ErrorMessage name="categoryName" component="div" />
                <input
                  type="file"
                  accept="image/jpeg,image/png,image/jpg,image/gif"
                  onChange={(event) => setFieldValue("file", event.currentTarget.files[0])}
                />
                <ErrorMessage name="file" component="div" />
                <button className="text-gray-500" type="submit">Save</button>
                <button className="text-gray-500" type="button" onClick={() => setModalData(null)}>
                  Cancel
                </button>
              </Form>
            )}
          </Formik>
        </div>
      )}
    </div>
  );
}
